// Protobuf binary is the only encoding a frame body ever carries, so no
// per-connection encoding is negotiated and none is named here. A
// non-Rust client reaches the daemon through the CLI's stdio bridge.

/// Connection purpose stated in ConnHello for routing and output shaping.
/// The daemon admits only arms matching the mode's `modes=` list. The
/// peer states its own mode, so this is routing, never authorization
/// (which requires credentials a peer cannot mint for itself).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, ::prost::Enumeration)]
#[repr(i32)]
pub enum ConnectionMode {
    Unspecified = 0,
    /// Interactive window: attaches and streams one session; the only mode
    /// the daemon pushes Reattach / SessionExited / RetargetHost to.
    Window = 1,
    /// Scripted operator (the felis sessions verbs): the whole Ops family,
    /// plus an attach where a verb drives or reads a session.
    Ops = 2,
    /// Notification observer: the Notify family and nothing else. Its
    /// --session filter rides Subscribe.session_prefix, so it needs no
    /// roster query of its own.
    Observer = 3,
}
