/// Why a stream ended badly (ConnError). A closed set rather than a bare
/// string: the client picks its remedy from the reason (retry a
/// narrowed request, back off until a stream frees up, give up), and
/// `detail` only says which value provoked it.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, ::prost::Enumeration)]
#[repr(i32)]
pub enum StreamErrorReason {
    Unspecified = 0,
    /// The request itself was malformed or unservable as asked (an empty
    /// search needle, a regex that does not compile). Re-issuing the same
    /// request fails the same way.
    InvalidRequest = 1,
    /// The connection already holds the maximum outstanding streams the
    /// daemon serves it. The refused stream is the only casualty: the
    /// connection stays usable, and the request is worth retrying once an
    /// earlier stream terminates.
    TooManyStreams = 2,
    /// The subject went away mid-flight: the session ended, or the daemon
    /// is shutting down. Nothing about the request was wrong.
    Unavailable = 3,
    /// The daemon abandoned the stream on its own fault (a row-encode
    /// failure shipped a truncated burst).
    Internal = 4,
}
